# From submission-mammals: Rscript --vanilla reproduce/01_terminal.R
stopifnot(file.exists('data/mammals-49-tree.nwk'))
for(f in c('app_tasks.R','core_mod_data_base.R','core_mod_signal_signal.R','core_mod_signal_PGLS.R'))source(file.path('source',f))
tree<-ape::read.tree('data/mammals-49-tree.nwk');z<-read.csv('data/mammals-49-traits.csv',check.names=FALSE)
stopifnot(nrow(z)==49,identical(z$taxon,tree$tip.label),all(abs(z$ln_body_mass_kg-log(z$body_mass_kg))<1e-12),all(abs(z$ln_home_range_km2-log(z$home_range_km2))<1e-12))
signal<-guane_signal(tree,z,'taxon','ln_home_range_km2',seed=20261201,nsim=999)
pgls<-guane_pgls(tree,z,'taxon','ln_home_range_km2','ln_body_mass_kg',model='BM',method='REML')
write.csv(signal,'terminal/signal.csv',row.names=FALSE);write.csv(pgls$coefficients,'terminal/pgls.csv',row.names=FALSE);write.csv(pgls$points,'terminal/residuals.csv',row.names=FALSE)
writeLines(if(length(pgls$warnings))pgls$warnings else 'No fitting warnings','terminal/warnings.txt')
x<-setNames(z$ln_home_range_km2,z$taxon)
refK<-phytools::phylosig(tree,x,method='K',test=FALSE);refL<-phytools::phylosig(tree,x,method='lambda',test=TRUE)
refFit<-nlme::gls(ln_home_range_km2~ln_body_mass_kg,data=z,correlation=ape::corBrownian(phy=tree,form=~taxon),method='REML')
stopifnot(isTRUE(all.equal(as.numeric(refK),signal$Estimate[1],tolerance=1e-10)),isTRUE(all.equal(refL$lambda,signal$Estimate[2],tolerance=1e-10)),isTRUE(all.equal(unname(coef(refFit)),pgls$coefficients$Estimate,tolerance=1e-10)))
saveRDS(list(tree=tree,traits=z,signal=signal,pgls=pgls),'terminal/fits.rds')
capture.output(sessionInfo(),file='terminal/sessionInfo.txt')
cat('PASS: 49 matched inputs; transformations correct; GUANE estimates match direct backend calls.\n');print(signal);print(pgls$coefficients)
